const exec = $json.execution || {};
const wf   = $json.workflow  || {};
const err  = $json.error     || {};
const node = err.node        || {};

const ts = new Date().toLocaleTimeString('es-ES', { timeZone: 'America/Bogota', hour12: false });

const msg =
  `❌ <b>Error en N8N</b>\n` +
  `⏰ ${ts}\n\n` +
  `📋 <b>Workflow:</b> ${wf.name || 'desconocido'}\n` +
  `🔧 <b>Nodo:</b> ${node.name || 'desconocido'}\n\n` +
  `💬 <b>Error:</b>\n<pre>${String(err.message || 'sin detalle').slice(0, 500)}</pre>\n\n` +
  `🔗 <a href="${exec.url || 'https://n8n.esencialabs.co'}">Ver ejecución</a>`;

return [{ json: { message: msg } }];
